fn main() {
    // Phase 9: the app's own #[tauri::command]s must be DECLARED here, or
    // the ACL has no entry for them at all and every invoke from the
    // frontend fails with "Plugin not found" — even on local pages, even
    // with core:default. The list generates allow-<command> /
    // deny-<command> permissions (src-tauri/permissions/autogenerated/);
    // capabilities then grant the allow-* ones (see capabilities/*.json).
    // Keep this list in sync with the #[tauri::command] fns in src/main.rs.
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(
            tauri_build::AppManifest::new().commands(&[
                "hifz_set_recording_active",
                "hifz_is_recording_active",
                "hifz_web_base_url",
                "hifz_studio_open",
                "hifz_studio_close",
                "hifz_studio_is_open",
                "hifz_studio_layout",
            ]),
        ),
    )
    .expect("failed to run tauri-build");
}
